INSERT INTO `products` VALUES (1,'เก้าอี้ไม้โค้งอบอุ่น สไตล์เจแปนดิ',6900.00,'chair.jpg','งานไม้จริงดีไซน์โค้งมน ผสานความเรียบง่ายและอบอุ่น เข้ากับห้องโทนธรรมชาติได้อย่างลงตัว','2026-08-27 15:01:23','Best Seller','Japandi','เก้าอี้'),(2,'โซฟา รุ่น ARCOS ที่นั่งและพนักพิงหุ้มผ้า พร้อมหมอน 2 ใบ (ไม่มีรับประกัน)',14500.00,'sofa1.png\r\n','โปรโมชั่น : ช้อป 10000 ส่งฟรี!\r\nรายละเอียดโปรโมชั่น :\r\nส่งฟรี! เมื่อช้อปสินค้าครบ 10,000 บาท เงื่อนไขตามที่บริษัทกำหนด\r\nรับคะแนนสะสม : 676\r\nother: S','2026-08-27 15:01:23','New','Minimalist','โซฟา'),(3,'โต๊ะกลางหินอ่อน โมเดิร์นลักชูรี',4290.00,'โต๊ะ.avif','ขาเหล็กชุบสีทองพรีเมียม หน้าท็อปหินอ่อนแท้ หรูหราทันสมัยทุกมุมมอง','2026-08-27 15:01:23','Popular','Modern','โต๊ะกลาง'),(4,'เตียงนอนไม้สักธรรมชาติ เจแปนดิ',13590.00,'ที่นอน.avif','เตียงนอนที่ดีไซน์เรียบง่าย เน้นสัมผัสของไม้จริง ช่วยให้การพักผ่อนสมบูรณ์แบบ','2026-08-27 15:01:23','Recommended','Japandi','เตียงนอน'),(5,'ชั้นวางทีวี มินิมอลมูาด',18040.00,'ชั้นทีวี.avif','ดีไซน์ซ่อนสายไฟเรียบร้อย โทนสีไม้อ่อนละมุนตา เหมาะกับห้องพื้นที่จำกัด','2026-08-27 15:01:23','Trending','Minimalist','ชั้นวางทีวี'),(6,'ชุดโต๊ะทำงานผู้บริหาร โมเดิร์น',15900.00,'โต๊ะบริหาร.jpg','ดีไซน์เรียบหรู ดุดัน ทันสมัย เสริมภาพลักษณ์ความเป็นมืออาชีพให้ห้องทำงาน','2026-08-27 15:01:23','Luxury','Modern','โต๊ะทำงาน'),(8,'โซฟาเหล็กพ่นสี สไตล์โมเดิร์น',9600.00,'sofa-modern-1.jpg','โซฟาเหล็กพ่นสี ดีไซน์โมเดิร์น เส้นสายเรียบหรู ผลิตจากวัสดุคุณภาพสูง คัดสรรอย่างพิถีพิถันทุกขั้นตอน','2026-08-28 07:07:27','Best Seller','Modern','โซฟา'),(9,'โซฟาไม้สักธรรมชาติ สไตล์มินิมอล',17100.00,'sofa-minimalist-2.avif','โซฟาไม้สักธรรมชาติ มินิมอล เรียบง่าย ไม่ฟุ่มเฟือย เหมาะกับผู้ที่ต้องการยกระดับพื้นที่ให้ดูมีระดับและใช้งานได้จริง','2026-08-28 07:07:27','New','Minimalist','โซฟา'),(10,'โซฟาเหล็กพ่นสี สไตล์เจแปนดิ',43700.00,'sofa-japandi-3.png','โซฟาเหล็กพ่นสี สไตล์เจแปนดิ อบอุ่นเป็นธรรมชาติ เหมาะกับผู้ที่ต้องการยกระดับพื้นที่ให้ดูมีระดับและใช้งานได้จริง','2026-08-28 07:07:27','Limited Edition','Japandi','โซฟา'),(11,'เก้าอี้ทำงานหว